export const getListPaymentMethodRequestsUrl = (params?: ListPaymentMethodRequestsParams,) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {

    if (value !== undefined) {
      normalizedParams.append(key, value === null ? 'null' : String(value))
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0 ? `/api/payment-method-requests?${stringifiedParams}` : `/api/payment-method-requests`
}

